	defer c.Close()

	ctx := context.Background()

	// Query: list all roles from pg_roles with membership counts
	query := `
SELECT
  r.rolname as "Name",
  CASE WHEN r.rolsuper THEN 'yes' ELSE 'no' END as "Superuser",
  CASE WHEN r.rolinherit THEN 'yes' ELSE 'no' END as "Inherit",
  CASE WHEN r.rolcanlogin THEN 'yes' ELSE 'no' END as "Can Login",
  CASE WHEN r.rolreplication THEN 'yes' ELSE 'no' END as "Replication",
  CASE WHEN r.rolbypassrls THEN 'yes' ELSE 'no' END as "Bypass RLS",
  COUNT(m.member) FILTER (WHERE m.member IS NOT NULL) as "Members"
FROM pg_roles r
LEFT JOIN pg_auth_members m ON r.oid = m.roleid
GROUP BY r.oid, r.rolname, r.rolsuper, r.rolinherit, r.rolcanlogin, r.rolreplication, r.rolbypassrls
ORDER BY r.rolname
`

