// Helper functions

// validateRoleName validates PostgreSQL role name syntax
func validateRoleName(name string) error {
	if name == "" {
		return fmt.Errorf("role name cannot be empty")
	}
	if len(name) > 63 {
		return fmt.Errorf("role name cannot exceed 63 characters")
	}
	// Basic validation: alphanumeric, underscore, hyphen
	for _, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '-') {
			return fmt.Errorf("role name contains invalid characters; use alphanumeric, underscore, or hyphen")
		}
	}
	return nil
}

// quoteSQLIdentifier safely quotes a PostgreSQL identifier
func quoteSQLIdentifier(identifier string) string {
	return `"` + strings.ReplaceAll(identifier, `"`, `""`) + `"`
}

// escapeSQLString escapes a string for use in SQL
func escapeSQLString(s string) string {
	return strings.ReplaceAll(s, "'", "''")
}

// detectCircularMembership checks if granting member->container would create a cycle
func detectCircularMembership(ctx context.Context, c *client.Client, member, container string) error {
	// Simple check: does container have member in its membership chain?
	// This is a simplified circular detection; full implementation would trace the entire membership tree
	query := `
WITH RECURSIVE role_tree AS (
  SELECT roleid, memberid, 1 as depth
  FROM pg_auth_members
  WHERE memberid = (SELECT oid FROM pg_roles WHERE rolname = $1)
  UNION ALL
  SELECT am.roleid, am.memberid, rt.depth + 1
  FROM pg_auth_members am
  JOIN role_tree rt ON am.memberid = rt.roleid
  WHERE rt.depth < 100  -- Prevent infinite recursion
)
SELECT COUNT(*) > 0
FROM role_tree
WHERE roleid = (SELECT oid FROM pg_roles WHERE rolname = $2)
`

	var hasCycle bool
	err := c.QueryRow(ctx, query, member, container).Scan(&hasCycle)
	if err != nil {
		return apiErr("failed to check for circular membership: %v", err)
	}

	if hasCycle {
		return usageErr("circular membership detected: granting %s to %s would create a cycle", container, member)
	}

	return nil
}
